v8:item.v8:content:
// Поиск ставки НДС
//
Запрос = Новый Запрос();
Запрос.Текст = ""ВЫБРАТЬ
|	СтавкиНДС.Ссылка КАК СтавкаНДС
|ИЗ	
|	Справочник.СтавкиНДС КАК СтавкиНДС
|ГДЕ
|	СтавкиНДС."";
Если ТекстЯчейки = ""18"" Тогда
	Запрос.Текст = Запрос.Текст + ""Ставка = 18
	|	И НЕ СтавкиНДС.НеОблагается
	|	И НЕ СтавкиНДС.Расчетная"";
ИначеЕсли ТекстЯчейки = ""20"" Тогда
	Запрос.Текст = Запрос.Текст +""Ставка = 20
	|	И НЕ СтавкиНДС.НеОблагается
	|	И НЕ СтавкиНДС.Расчетная"";
ИначеЕсли ТекстЯчейки = ""22"" Тогда
	Запрос.Текст = Запрос.Текст +""Ставка = 22
	|	И НЕ СтавкиНДС.НеОблагается
	|	И НЕ СтавкиНДС.Расчетная"";
ИначеЕсли ТекстЯчейки = ""10"" Тогда
	Запрос.Текст = Запрос.Текст +""Ставка = 10
	|	И НЕ СтавкиНДС.НеОблагается
	|	И НЕ СтавкиНДС.Расчетная"";
ИначеЕсли ТекстЯчейки = ""0"" Тогда
	Запрос.Текст = Запрос.Текст + ""Ставка = 0
	|	И НЕ СтавкиНДС.НеОблагается"";
Иначе
	Запрос.Текст = Запрос.Текст + "НеОблагается";
КонецЕсли;

Результат = Справочники.СтавкиНДС.ПустаяСсылка();
Выборка = Запрос.Выполнить().Выбрать();
Если Выборка.Следующий() Тогда
	Результат = Выборка.СтавкаНДС;
КонецЕсли;
